problems.solutionCode:
function createWebhookDispatchers(endpoints) {
  if (!Array.isArray(endpoints)) {
    throw new TypeError('endpoints must be an array');
  }
  const dispatchers = [];
  for (let i = 0; i < endpoints.length; i += 1) {
    const endpoint = endpoints[i];
    if (typeof endpoint !== 'string' || endpoint.trim() === '') {
      throw new TypeError('each endpoint must be a non-empty string');
    }
    dispatchers.push(() => ({ index: i, endpoint }));
  }
  return dispatchers;
}

module.exports = { createWebhookDispatchers };

