function resolveTenantQuotas(baseQuota, overrideQuota) {
  if (!Number.isFinite(baseQuota) || baseQuota < 0) {
    throw new RangeError('baseQuota must be a finite non-negative number');
  }
  let effectiveQuota = baseQuota;
  let overridden = false;
  if (overrideQuota !== undefined && overrideQuota !== null) {
    if (!Number.isFinite(overrideQuota) || overrideQuota < 0) {
      throw new RangeError('overrideQuota must be a finite non-negative number');
    }
    const effectiveQuota = overrideQuota;
    overridden = effectiveQuota >= 0;
  }
  return { baseQuota, effectiveQuota, overridden };
}

module.exports = { resolveTenantQuotas };

problems.solutionCode:
function isValidQuota(value) {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0;
}

function resolveTenantQuotas(baseQuota, overrideQuota) {
  if (!isValidQuota(baseQuota)) {
    throw new RangeError('baseQuota must be a finite non-negative number');
  }
  if (overrideQuota !== undefined && overrideQuota !== null) {
    if (!isValidQuota(overrideQuota)) {
      throw new RangeError('overrideQuota must be a finite non-negative number');
    }
    return { baseQuota, effectiveQuota: overrideQuota, overridden: true };
  }
  return { baseQuota, effectiveQuota: baseQuota, overridden: false };
}

module.exports = { resolveTenantQuotas };

