function createScopedAuditEntry(defaultActor, overrideActor, action) {
  if (typeof defaultActor !== 'string' || defaultActor.trim() === '') {
    throw new TypeError('defaultActor must be a non-empty string');
  }
  if (typeof action !== 'string' || action.trim() === '') {
    throw new TypeError('action must be a non-empty string');
  }
  const fallbackActor = defaultActor.trim();
  function readActor() {
    return fallbackActor;
  }
  function runWithOverride() {
    if (overrideActor !== undefined && overrideActor !== null) {
      if (typeof overrideActor !== 'string' || overrideActor.trim() === '') {
        throw new TypeError('overrideActor must be a non-empty string');
      }
      const activeActor = overrideActor.trim();
      return { actor: readActor(), action: action.trim(), usedOverride: Boolean(activeActor) };
    }
    return { actor: readActor(), action: action.trim(), usedOverride: false };
  }
  return runWithOverride();
}

module.exports = { createScopedAuditEntry };

problems.solutionCode:
function assertNonEmptyString(value, label) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value.trim();
}

function createScopedAuditEntry(defaultActor, overrideActor, action) {
  const normalizedDefault = assertNonEmptyString(defaultActor, 'defaultActor');
  const normalizedAction = assertNonEmptyString(action, 'action');
  if (overrideActor !== undefined && overrideActor !== null) {
    const normalizedOverride = assertNonEmptyString(overrideActor, 'overrideActor');
    return { actor: normalizedOverride, action: normalizedAction, usedOverride: true };
  }
  return { actor: normalizedDefault, action: normalizedAction, usedOverride: false };
}

module.exports = { createScopedAuditEntry };

